1	package renamecheck
2	
3	import (
4		"bufio"
5		"fmt"
6		"io"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"regexp"
11		"sort"
12		"strings"
13	)
14	
15	type Finding struct {
16		Path    string
17		Line    int
18		Column  int
19		Surface string
20		Match   string
21	}
22	
23	type Options struct {
24		Root string
25		Out  io.Writer
26	}
27	
28	type rule struct {
29		surface string
30		re      *regexp.Regexp
31		rootGo  bool
32	}
33	
34	var rules = []rule{
35		{surface: "github.com/DocumentDrivenDX/agent", re: regexp.MustCompile(regexp.QuoteMeta("github.com/DocumentDrivenDX/agent"))},
36		{surface: "root package agent", re: regexp.MustCompile(`^\s*package\s+agent\s*$`), rootGo: true},
37		{surface: "ddx-agent", re: regexp.MustCompile(regexp.QuoteMeta("ddx-agent"))},
38		{surface: "DDX Agent/DDx Agent", re: regexp.MustCompile(`DD[Xx] Agent`)},
39		{surface: ".agent", re: regexp.MustCompile(`(^|[^A-Za-z0-9_])\.agent([^A-Za-z0-9_]|$)`)},
40		{surface: "~/.config/agent", re: regexp.MustCompile(regexp.QuoteMeta("~/.config/agent"))},
41		{surface: "AGENT_*/DDX_AGENT_*", re: regexp.MustCompile(`\b(?:DDX_AGENT|AGENT)_[A-Z0-9_]+\b`)},
42	}
43	
44	var skippedDirs = map[string]bool{
45		".git":                 true,
46		".ddx":                 true,
47		".agents":              true,
48		".claude":              true,
49		".helix-ratchets":      true,
50		"docs/helix":           true,
51		"docs/research":        true,
52		"internal/renamecheck": true,
53		// DDX_AGENT_* harness env vars are not yet renamed; allowlisted until a
54		// dedicated harness-rename bead updates them.
55		"internal/harnesses": true,
56	}
57	
58	var skippedFiles = map[string]bool{
59		"CHANGELOG.md": true,
60		// Root-level service test files that reference DDX_AGENT_* harness env vars
61		// which have not yet been renamed. Allowlisted until the harness-rename bead
62		// is complete.
63		"harness_golden_integration_test.go": true,
64		"service_providers_test.go":          true,
65		"service_route_attempts_test.go":     true,
66		"service_status_test.go":             true,
67	}
68	
69	func Scan(opts Options) ([]Finding, error) {
70		root := opts.Root
71		if root == "" {
72			root = "."
73		}
74	
75		var findings []Finding
76		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
77			if err != nil {
78				return err
79			}
80			rel, err := filepath.Rel(root, path)
81			if err != nil {
82				return err
83			}
84			rel = filepath.ToSlash(rel)
85			if rel == "." {
86				return nil
87			}
88			if d.IsDir() {
89				if shouldSkipDir(rel) {
90					return filepath.SkipDir
91				}
92				return nil
93			}
94			if skippedFiles[rel] {
95				return nil
96			}
97			if !isTextCandidate(rel) {
98				return nil
99			}
100			fileFindings, err := scanFile(root, rel)
101			if err != nil {
102				return err
103			}
104			findings = append(findings, fileFindings...)
105			return nil
106		})
107		if err != nil {
108			return nil, err
109		}
110		sort.Slice(findings, func(i, j int) bool {
111			if findings[i].Path != findings[j].Path {
112				return findings[i].Path < findings[j].Path
113			}
114			if findings[i].Line != findings[j].Line {
115				return findings[i].Line < findings[j].Line
116			}
117			return findings[i].Column < findings[j].Column
118		})
119		return findings, nil
120	}
121	
122	func Report(w io.Writer, findings []Finding) error {
123		if w == nil {
124			return nil
125		}
126		if len(findings) == 0 {
127			_, err := fmt.Fprintln(w, "rename-noise: no unallowlisted old-name hits found")
128			return err
129		}
130		if _, err := fmt.Fprintf(w, "rename-noise: %d unallowlisted old-name hit(s)\n", len(findings)); err != nil {
131			return err
132		}
133		for _, f := range findings {
134			if _, err := fmt.Fprintf(w, "%s:%d:%d: %s: %q\n", f.Path, f.Line, f.Column, f.Surface, f.Match); err != nil {
135				return err
136			}
137		}
138		return nil
139	}
140	
141	func Run(opts Options) ([]Finding, error) {
142		findings, err := Scan(opts)
143		if err != nil {
144			return nil, err
145		}
146		return findings, Report(opts.Out, findings)
147	}
148	
149	func scanFile(root, rel string) ([]Finding, error) {
150		file, err := os.Open(filepath.Join(root, filepath.FromSlash(rel)))
151		if err != nil {
152			return nil, err
153		}
154		defer file.Close()
155	
156		var findings []Finding
157		scanner := bufio.NewScanner(file)
158		buf := make([]byte, 0, 64*1024)
159		scanner.Buffer(buf, 1024*1024)
160		lineNo := 0
161		for scanner.Scan() {
162			lineNo++
163			line := scanner.Text()
164			for _, r := range rules {
165				if r.rootGo && !isRootGoFile(rel) {
166					continue
167				}
168				loc := r.re.FindStringIndex(line)
169				if loc == nil {
170					continue
171				}
172				findings = append(findings, Finding{
173					Path:    rel,
174					Line:    lineNo,
175					Column:  loc[0] + 1,
176					Surface: r.surface,
177					Match:   line[loc[0]:loc[1]],
178				})
179			}
180		}
181		return findings, scanner.Err()
182	}
183	
184	func shouldSkipDir(rel string) bool {
185		if skippedDirs[rel] {
186			return true
187		}
188		for dir := range skippedDirs {
189			if strings.HasPrefix(rel, dir+"/") {
190				return true
191			}
192		}
193		return false
194	}
195	
196	func isRootGoFile(rel string) bool {
197		return filepath.Dir(rel) == "." && strings.HasSuffix(rel, ".go")
198	}
199	
200	func isTextCandidate(rel string) bool {
201		base := filepath.Base(rel)
202		if strings.HasPrefix(base, ".") && base != ".env" {
203			return false
204		}
205		switch filepath.Ext(rel) {
206		case ".go", ".md", ".txt", ".yaml", ".yml", ".json", ".jsonl", ".toml", ".sh", ".py", ".env":
207			return true
208		default:
209			return base == "Makefile" || base == "Dockerfile" || base == "go.mod"
210		}
211	}
